package main

import (
	"database/sql"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"linkshelf/internal/api"
	"linkshelf/internal/store"

	_ "modernc.org/sqlite"
)

func newServer() http.Handler {
	handler := api.NewHandler()
	mux := http.NewServeMux()

	mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"status":"ok"}`))
	})

	mux.Handle("/api/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if strings.HasPrefix(r.URL.Path, "/api/items") {
			if r.Method != http.MethodGet && r.Method != http.MethodPost && r.Method != http.MethodDelete {
				http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
				return
			}
			clone := r.Clone(r.Context())
			clone.URL.Path = strings.Replace(clone.URL.Path, "/api/items", "/api/links", 1)
			handler.ServeHTTP(w, clone)
			return
		}
		handler.ServeHTTP(w, r)
	}))

	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/" && r.Method == http.MethodGet {
			for _, candidate := range []string{
				filepath.Join("web", "index.html"),
				filepath.Join("..", "..", "web", "index.html"),
			} {
				if _, err := os.Stat(candidate); err == nil {
					http.ServeFile(w, r, candidate)
					return
				}
			}
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			_, _ = w.Write([]byte("<!doctype html><html><head><title>LinkShelf</title></head><body><h1>LinkShelf</h1></body></html>"))
			return
		}
		if r.URL.Path == "/" {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}
		handler.ServeHTTP(w, r)
	})
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if strings.Contains(r.URL.Path, "..") {
			http.NotFound(w, r)
			return
		}
		mux.ServeHTTP(w, r)
	})
}

func main() {
	db, err := sql.Open("sqlite", "linkshelf.db")
	if err != nil {
		log.Fatalf("open database: %v", err)
	}
	defer db.Close()

	if err := store.InitSchema(db); err != nil {
		log.Fatalf("initialize schema: %v", err)
	}
	store.DB = db

	log.Println("listening on :8080")
	if err := http.ListenAndServe(":8080", newServer()); err != nil {
		log.Fatalf("serve HTTP: %v", err)
	}
}

